import os
def fetch_endpoint(timeout_sec: int = 10) -> str:
    token = os.getenv('API_TOKEN', '')
    if not token:
        raise RuntimeError('Missing API_TOKEN in environment')
    return f'Bearer {token} ({timeout_sec}s)'
